package com.jinloes.practice;
import java.util.*;
public class Solution { private record E(int value,int run,int index){} public static int[] sortAlternatingRuns(int[] values){ if(values.length<=1)return values.clone(); List<int[]> runs=new ArrayList<>(); int start=0; boolean inc=true; for(int i=1;i<=values.length;i++){ if(i==values.length||(inc?values[i]<values[i-1]:values[i]>values[i-1])){ int[] run=new int[i-start]; if(inc) for(int j=start;j<i;j++)run[j-start]=values[j]; else for(int j=i-1;j>=start;j--)run[i-1-j]=values[j]; runs.add(run); start=i; inc=!inc; } } PriorityQueue<E> h=new PriorityQueue<>((a,b)->Integer.compare(a.value,b.value)); for(int r=0;r<runs.size();r++) if(runs.get(r).length>0) h.add(new E(runs.get(r)[0],r,0)); int[] out=new int[values.length]; int w=0; while(!h.isEmpty()){ E e=h.remove(); out[w++]=e.value; int ni=e.index+1; int[] run=runs.get(e.run); if(ni<run.length) h.add(new E(run[ni],e.run,ni)); } return out; } }
